// Get the raw JSON string from OpenRouter ('Smart AI1')
const aiItem = $('Smart AI1').first();
let rawString = '';
// Auto-detect common OpenRouter fields (from pinned output, adjust if needed)
if (aiItem) {
  rawString = aiItem.json.message?.content ||  // Standard OpenRouter API
              aiItem.json.content ||
              aiItem.json.text ||
              aiItem.json.output ||
              aiItem.json.response ||
              aiItem.json.body ||
              '';
}
if (!rawString || typeof rawString !== 'string') {
  return [{ json: { workflow: [], error: 'No JSON string found. Check field paths or pin Smart AI1 output.' } }];
}

// --- UPDATED SECTION ---
// First, check if the string begins with text that suggests it's an essay or other text content
// rather than JSON data
const textContentIndicators = [
  "Here's", "Here is", "Essay", "Article", "Content", "Text", 
  "I've created", "I have created", "Below is"
];

// If it looks like text content rather than JSON data, wrap it in a proper JSON structure
if (textContentIndicators.some(indicator => rawString.trim().startsWith(indicator))) {
  // It's clearly text content - wrap it in a workflow structure
  const wrappedWorkflow = { 
    workflow: [],
    content: rawString.trim() 
  };
  return [{ json: wrappedWorkflow }];
}

// Otherwise continue with the original JSON parsing logic
let stringToParse = rawString.trim(); // Trim leading/trailing whitespace

// Sometimes AI might output introductory text or markdown wrappers that hide the JSON.
// We need to robustly extract the actual JSON block.
let jsonMatch = stringToParse.match(/```json\n([\s\S]*?)\n```/); // Match markdown code blocks
if (jsonMatch && jsonMatch[1]) {
    stringToParse = jsonMatch[1].trim();
} else {
    // Fallback: If no markdown block, try to find the first '{' and last '}'
    const firstBrace = stringToParse.indexOf('{');
    const lastBrace = stringToParse.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
        stringToParse = stringToParse.substring(firstBrace, lastBrace + 1).trim();
    } else if (firstBrace === -1) {
        // If no JSON structure is found at all, treat as plain text
        const wrappedWorkflow = { 
          workflow: [],
          content: rawString.trim() 
        };
        return [{ json: wrappedWorkflow }];
    }
}
// --- END OF UPDATED SECTION ---

// Parse to JSON object
let parsedWorkflow = { workflow: [] };
let errorMsg = null;
try {
  // Directly parse the (potentially extracted) string.
  parsedWorkflow = JSON.parse(stringToParse);
} catch (error) {
  // If JSON parsing fails, treat the content as plain text
  return [{ 
    json: { 
      workflow: [], 
      content: rawString.trim(),
      parseAttempted: true 
    } 
  }];
}

// Output: Parsed object (full workflow) or content wrapper
return [{ json: parsedWorkflow }];

