// Get all input items
const items = $input.all();
let combinedText = "";
let aiOutput = "";

// Loop through all items
for (let i = 0; i < items.length; i++) {
  // Get the AI output text from each item
  if (items[i].json && items[i].json.text) {
    aiOutput = items[i].json.text;

    // Add separator if not the first entry
    if (combinedText && aiOutput) {
      combinedText += "\n\n\n\n";  // Double line break
    }

    // Add the output
    combinedText += aiOutput;
  }
}

// Return the combined text
return {
  json: {
    combinedText: combinedText,
    itemCount: items.length
  }
};
